tered\", async () => {\n    function Component() {\n      const { control, handleSubmit } = useForm({\n        defaultValues: {\n          test: [{ firstName: 'Bill', lastName: '' }],\n        },\n      });\n      const { fields, append, remove } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(noop)}>\n          <ul>\n            {fields.map((item, index) => {\n              return (\n                <li key={item.id}>\n                  <Controller\n                    name={`test.${index}.lastName` as const}\n                    control={control}\n                    render={({ field }) => <input {...field} />}\n                  />\n                  <button type=\"button\" onClick={() => remove(index)}>\n                    Delete\n                  </button>\n                </li>\n              );\n            })}\n          </ul>\n          <button\n            type=\"button\"\n            onClick={() => {\n              append({ firstName: 'appendBill', lastName: 'appendLuo' });\n            }}\n          >\n            append\n          </button>\n        </form>\n      );\n    }\n\n    render(<Component />);\n\n    fireEvent.input(screen.getAllByRole('textbox')[0], {\n      target: { name: 'test[0].lastName', value: '111' },\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n    fireEvent.click(screen.getAllByRole('button', { name: 'Delete' })[1]);\n\n    expect(\n      (screen.getAllByRole('textbox')[0] as HTMLInputElement).value,\n    ).toEqual('111');\n  });\n\n  describe('with resolver', () => {\n    it('should invoke resolver when formState.isValid true', async () => {\n      const resolver = jest.fn().mockReturnValue({});\n\n      const { result } = renderHook(() => {\n        const { formState, control } = useForm({\n          mode: VALIDATION_MODE.onChange,\n          resolver,\n          defaultValues: {\n            test: [{ value: 'test' }],\n          },\n        });\n        const { remove } = useFieldArray({ control, name: 'test' });\n        return { formState, remove };\n      });\n\n      result.current.formState.isValid;\n\n      await act(async () => {\n        result.current.remove(0);\n      });\n\n      expect(resolver).toHaveBeenCalledWith(\n        {\n          test: [],\n        },\n        undefined,\n        { criteriaMode: undefined, fields: {}, names: [] },\n      );\n    });\n\n    it('should not invoke resolver when formState.isValid false', () => {\n      const resolver = jest.fn().mockReturnValue({});\n\n      const { result } = renderHook(() => {\n        const { formState, control } = useForm({\n          mode: VALIDATION_MODE.onChange,\n          resolver,\n          defaultValues: {\n            test: [{ value: 'test' }],\n          },\n        });\n        const { remove } = useFieldArray({ control, name: 'test' });\n        return { formState, remove };\n      });\n\n      act(() => {\n        result.current.remove(0);\n      });\n\n      expect(resolver).toHaveBeenCalled();\n    });\n\n    it('should remove the first index correctly', async () => {\n      let output: unknown;\n\n      type FormValues = {\n        test: {\n          firstName: string;\n          lastName: string;\n        }[];\n      };\n\n      const Component = () => {\n        const { control, handleSubmit, register } = useForm<FormValues>({\n          defaultValues: {\n            test: [\n              {\n                firstName: 'test',\n                lastName: 'test',\n              },\n              {\n                firstName: 'test1',\n                lastName: 'test1',\n              },\n            ],\n          },\n        });\n        const { fields, remove } = useFieldArray({\n          control,\n          name: 'test',\n        });\n\n        const onSubmit = (data: FormValues) => (output = data);\n\n        return (\n          <form onSubmit={handleSubmit(onSubmit)}>\n            {