+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/reset.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { Controller } from '../../controller';\nimport type {\n  Control,\n  FieldErrors,\n  UseFormRegister,\n  UseFormReturn,\n} from '../../types';\nimport { useController } from '../../useController';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\nimport { useWatch } from '../../useWatch';\nimport isEmptyObject from '../../utils/isEmptyObject';\nimport noop from '../../utils/noop';\n\njest.useFakeTimers();\n\ndescribe('reset', () => {\n  it('should reset the form and re-render the form', async () => {\n    const { result } = renderHook(() => useForm<{ test: string }>());\n\n    result.current.register('test');\n    result.current.setValue('test', 'data');\n\n    expect(result.current.formState.isSubmitted).toBeFalsy();\n    await act(async () => {\n      await result.current.handleSubmit((data) => {\n        expect(data).toEqual({\n          test: 'data',\n        });\n      })({\n        preventDefault: noop,\n        persist: noop,\n      } as React.SyntheticEvent);\n    });\n\n    expect(result.current.formState.isSubmitted).toBeTruthy();\n    act(() => result.current.reset());\n    expect(result.current.formState.isSubmitted).toBeFalsy();\n  });\n\n  it('should reset form value', () => {\n    let methods: any;\n    const App = () => {\n      methods = useForm<{\n        test: string;\n      }>();\n      return (\n        <form>\n          <input {...methods.register('test')} />\n        </form>\n      );\n    };\n    render(<App />);\n\n    act(() =>\n      methods.reset({\n        test: 'test',\n      }),\n    );\n\n    expect(methods.getValues()).toEqual({\n      test: 'test',\n    });\n  });\n\n  it('should reset the form with callback action', () => {\n    const App = () => {\n      const { register, reset } = useForm({\n        defaultValues: {\n          test: '',\n        },\n      });\n\n      React.useEffect(() => {\n        reset((formValues) => {\n          return {\n            ...formValues,\n            test: 'test',\n          };\n        });\n      }, [reset]);\n\n      return (\n        <form>\n          <input {...register('test')} />\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n  });\n\n  it('should set array value of multiple checkbox inputs correctly', async () => {\n    const App = () => {\n      const { register } = useForm<{\n        test: string[];\n      }>({\n        defaultValues: {\n          test: ['1', '2'],\n        },\n      });\n\n      return (\n        <>\n          <input type=\"checkbox\" value={'1'} {...register('test')} />\n          <input type=\"checkbox\" value={'2'} {...register('test')} />\n        </>\n      );\n    };\n\n    render(<App />);\n\n    screen\n      .getAllByRole('checkbox')\n      .forEach((checkbox) =>\n        expect((checkbox as HTMLInputElement).checked).toBeTruthy(),\n      );\n  });\n\n  it('should reset the form if ref is HTMLElement and parent element is not form', async () => {\n    const mockReset = jest.spyOn(window.HTMLFormElement.prototype, 'reset');\n    let methods: UseFormReturn<{\n      test: string;\n    }>;\n    const App = () => {\n      methods = useForm<{\n        test: string;\n      }>();\n      return <input {...methods.register('test')} />;\n    };\n    render(<App />);\n\n    act(() => methods.reset());\n\n    expect(mockReset).not.toHaveBeenCalled();\n  });\n\n  it('should set default value if values is specified to first argument', async () => {\n    const { result } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n\n    act(() => result.current.reset({ test: 'test' }));\n\n    expect(result.current.control._defaultValues).toEqual({\n      test: 'test',\n    });\n  });\n\n  it('should reset unmountFieldsState value when shouldUnregister set to false', () => {\n    const { result } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n\n    act(() => result.current.reset({ test: 'test' }));\n  });\n\n  it('should not reset unmountFieldsState value by default', () => {\n    const { result } = renderHook(() =>\n      useForm<{\n        test: string;\n      }>(),\n    );\n\n    result.current.register('test');\n\n    act(() => result.current.reset({ test: 'test' }));\n  });\n\n  it('should not reset form values when keepValues is specified', () => {\n    const App = () => {\n      const { register, reset } = useForm();\n\n      return (\n        <>\n          <input {...register('test')} />\n          <button\n            type={'button'}\n            onClick={() =>\n              reset(undefined, {\n                keepValues: true,\n              })\n            }\n          >\n            reset\n          </button>\n        </>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n  });\n\n  it('should not reset form defaultValues when keepDefaultValues is specified', async () => {\n    const App = () => {\n      const {\n        register,\n        reset,\n        formState: { isDirty },\n      } = useForm({\n        defaultValues: {\n          test: 'test1',\n        },\n      });\n\n      return (\n        <>\n          <input {...register('test')} />\n          <p>{isDirty ? 'dirty' : ''}</p>\n          <button\n            type={'button'}\n            onClick={() =>\n              reset(undefined, {\n                keepValues: true,\n              })\n            }\n          >\n            reset\n          </button>\n        </>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test2',\n      },\n    });\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test1',\n      },\n    });\n\n    expect(screen.queryByText('dirty')).not.toBeInTheDocument();\n  });\n\n  it('should update dirty and dirtyFields when keepDefaultValues and updatedValues is provided', async () => {\n    function App() {\n      const {\n        register,\n        reset,\n        formState: { isDirty, dirtyFields },\n      } = useForm({\n        defaultValues: {\n          firstName: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('firstName')} placeholder=\"First Name\" />\n          <p>{isDirty ? 'dirty' : 'pristine'}</p>\n          <p>{JSON.stringify(dirtyFields)}</p>\n\n          <button\n            type=\"button\"\n            onClick={() => {\n              reset(\n                {\n                  firstName: 'other',\n                },\n                {\n                  keepDefaultValues: true,\n                },\n              );\n            }}\n          >\n            test\n          </button>\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n    expect(screen.getByText('{\"firstName\":true}')).toBeVisible();\n  });\n\n  it('should not reset if keepStateOption is specified', async () => {\n    let formState = {};\n    const onSubmit = jest.fn();\n\n    const App = () => {\n      const {\n        register,\n        handleSubmit,\n        reset,\n        formState: { touchedFields, errors, isDirty },\n      } = useForm<{ test: string }>({\n        defaultValues: {\n          test: '',\n        },\n      });\n\n      formState = { touchedFields, errors, isDirty };\n\n      return (\n        <form onSubmit={handleSubmit(onSubmit)}>\n          <input {...register('test', { required: true, minLength: 3 })} />\n          <button>submit</button>\n          <button\n            onClick={() => {\n              reset(\n                { test: '' },\n                {\n                  keepErrors: true,\n                  keepDirty: true,\n                  keepIsSubmitted: true,\n                  keepIsSubmitSuccessful: true,\n                  keepTouched: true,\n                  keepSubmitCount: true,\n                },\n              );\n            }}\n            type={'button'}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    await waitFor(() => expect(onSubmit).toHaveBeenCalled());\n    await waitFor(() =>\n      expect(formState).toEqual({\n        errors: {},\n        isDirty: true,\n        touchedFields: {\n          test: true,\n        },\n      }),\n    );\n\n    fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n    expect(formState).toEqual({\n      errors: {},\n      isDirty: true,\n      touchedFields: {\n        test: true,\n      },\n    });\n  });\n\n  it('should reset field array fine with empty value', async () => {\n    let data: unknown;\n    const App = () => {\n      const { control, register, reset, handleSubmit } = useForm<{\n        test: {\n          firstName: string;\n          lastName: string;\n        }[];\n      }>();\n      const { fields } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form\n          onSubmit={handleSubmit((d) => {\n            data = d;\n          })}\n        >\n          {fields.map((field, index) => (\n            <div key={field.id}>\n              <input {...register(`test.${index}.firstName` as const)} />\n              <Controller\n                control={control}\n                name={`test.${index}.lastName` as const}\n                render={({ field }) => <input {...field} />}\n              />\n            </div>\n          ))}\n\n          <button>submit</button>\n\n          <button type={'button'} onClick={() => reset()}>\n            reset\n          </button>\n          <button\n            type={'button'}\n            onClick={() =>\n              reset({\n                test: [{ firstName: 'test', lastName: 'test' }],\n              })\n            }\n          >\n            reset with value\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    const resetButton = screen.getByRole('button', { name: 'reset' });\n    const submitButton = screen.getByRole('button', { name: 'submit' });\n\n    fireEvent.click(resetButton);\n    fireEvent.click(submitButton);\n\n    await waitFor(() => expect(data).toEqual({}));\n\n    fireEvent.click(screen.getByRole('button', { name: 'reset with value' }));\n    fireEvent.click(submitButton);\n\n    await waitFor(() =>\n      expect(data).toEqual({\n        test: [{ firstName: 'test', lastName: 'test' }],\n      }),\n    );\n  });\n\n  it('should return reset nested value', () => {\n    const getValuesResult: unknown[] = [];\n\n    function App() {\n      const [, update] = React.useState({});\n      const { register, reset, getValues } = useForm<{\n        names: { name: string }[];\n      }>({\n        defaultValues: {\n          names: [{ name: 'test' }],\n        },\n      });\n\n      React.useEffect(() => {\n        reset({ names: [{ name: 'Bill' }, { name: 'Luo' }] });\n      }, [reset]);\n\n      getValuesResult.push(getValues());\n\n      return (\n        <form>\n          <input {...register('names.0.name')} placeholder=\"Name\" />\n          <button type={'button'} onClick={() => update({})}>\n            update\n          </button>\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(getValuesResult).toEqual([\n      {\n        names: [\n          {\n            name: 'test',\n          },\n        ],\n      },\n      {\n        names: [\n          {\n            name: 'Bill',\n          },\n          {\n            name: 'Luo',\n          },\n        ],\n      },\n      {\n        names: [\n          {\n            name: 'Bill',\n          },\n          {\n            name: 'Luo',\n          },\n        ],\n      },\n    ]);\n  });\n\n  it('should keep defaultValues after reset with shouldKeepDefaultValues', async () => {\n    type FormValues = { test: string; test1: string };\n    const ControlledInput = ({ control }: { control: Control<FormValues> }) => {\n      const { field } = useController({\n        name: 'test',\n        control,\n      });\n\n      return <input {...field} />;\n    };\n\n    function App() {\n      const { control, register, reset } = useForm<FormValues>({\n        defaultValues: { test: 'test', test1: 'test1' },\n      });\n      const resetData = () => {\n        reset(undefined, { keepDefaultValues: true });\n      };\n\n      return (\n        <form>\n          <ControlledInput control={control} />\n          <input {...register('test1')} />\n          <input type=\"button\" onClick={resetData} value=\"Reset\" />\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.change(screen.getAllByRole('textbox')[0], {\n      target: { value: 'data' },\n    });\n\n    fireEvent.change(screen.getAllByRole('textbox')[1], {\n      target: { value: 'data' },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(\n      (screen.getAllByRole('textbox')[0] as HTMLInputElement).value,\n    ).toEqual('test');\n    expect(\n      (screen.getAllByRole('textbox')[1] as HTMLInputElement).value,\n    ).toEqual('test1');\n  });\n\n  describe('when reset optional props set to keepDirtyValues', () => {\n    describe('with uncontrolled components', () => {\n      let updatedDirtyFields: Record<string, boolean> = {};\n      let updatedDirty = false;\n      let submittedValue: unknown = {};\n\n      function App() {\n        const [showButton, setShowButton] = React.useState(false);\n        const {\n          reset,\n          register,\n          handleSubmit,\n          formState: { dirtyFields, isDirty },\n        } = useForm();\n\n        updatedDirtyFields = dirtyFields;\n        updatedDirty = isDirty;\n\n        React.useEffect(() => {\n          setTimeout(() => {\n            reset(\n              {\n                firstName: 'bill',\n                lastName: 'luo',\n              },\n              { keepDirtyValues: true },\n            );\n            setShowButton(true);\n          }, 500);\n        }, [reset]);\n\n        return (\n          <form\n            onSubmit={handleSubmit((data) => {\n              submittedValue = data;\n            })}\n          >\n            <input {...register('firstName')} placeholder=\"First Name\" />\n            <input {...register('lastName')} placeholder=\"Last Name\" />\n\n            {showButton && (\n              <button\n                type=\"button\"\n                onClick={() => {\n                  reset();\n                }}\n              >\n                reset\n              </button>\n            )}\n            <button>submit</button>\n          </form>\n        );\n      }\n\n      it('should only update new reset values', async () => {\n        render(<App />);\n\n        await waitFor(() =>\n          expect(\n            (screen.getByPlaceholderText('First Name') as HTMLInputElement)\n              .value,\n          ).toEqual('bill'),\n        );\n\n        fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n        expect(updatedDirtyFields).toEqual({});\n        expect(updatedDirty).toBeFalsy();\n\n        expect(\n          (screen.getByPlaceholderText('First Name') as HTMLInputElement).value,\n        ).toEqual('bill');\n\n        expect(updatedDirtyFields).toEqual({});\n        expect(updatedDirty).toBeFalsy();\n\n        fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n        await waitFor(() =>\n          expect(submittedValue).toEqual({\n            firstName: 'bill',\n            lastName: 'luo',\n          }),\n        );\n      });\n\n      it('should treat previously-undirty fields as dirty when keepDefaultValues is set', async () => {\n        let updatedDirtyFields: Record<string, boolean> = {};\n        let updatedDirty = false;\n\n        function App() {\n          const {\n            reset,\n            register,\n            handleSubmit,\n            formState: { dirtyFields, isDirty },\n          } = useForm({ defaultValues: { firstName: '', lastName: '' } });\n\n          function resetKeepDefaults() {\n            reset(\n              {\n                firstName: 'bill',\n                lastName: 'luo',\n              },\n              {\n                keepDefaultValues: true,\n                keepDirtyValues: true,\n              },\n            );\n          }\n\n          updatedDirtyFields = dirtyFields;\n          updatedDirty = isDirty;\n\n          return (\n            <form\n              onSubmit={handleSubmit((data) => {\n                submittedValue = data;\n              })}\n            >\n              <input {...register('firstName')} placeholder=\"First Name\" />\n              <input {...register('lastName')} placeholder=\"Last Name\" />\n\n              <button\n                type=\"button\"\n                onClick={() => {\n                  resetKeepDefaults();\n                }}\n              >\n                reset keep defaults\n              </button>\n              <button>submit</button>\n            </form>\n          );\n        }\n\n        render(<App />);\n\n        fireEvent.click(\n          screen.getByRole('button', { name: 'reset keep defaults' }),\n        );\n\n        await waitFor(() =>\n          expect(\n            (screen.getByPlaceholderText('Last Name') as HTMLInputElement)\n              .value,\n          ).toEqual('luo'),\n        );\n\n        expect(\n          (screen.getByPlaceholderText('First Name') as HTMLInputElement).value,\n        ).toEqual('bill');\n\n        // Both fields were updated, the defaults were kept, so both should be dirty\n        expect(updatedDirtyFields).toEqual({\n          firstName: true,\n          lastName: true,\n        });\n\n        expect(updatedDirty).toBeTruthy();\n      });\n    });\n\n    describe('with controlled components', () => {\n      let updatedDirtyFields: Record<string, boolean> = {};\n      let updatedDirty = false;\n      let submittedValue: unknown = {};\n\n      function App() {\n        const [showButton, setShowButton] = React.useState(false);\n        const {\n          reset,\n          control,\n          handleSubmit,\n          formState: { dirtyFields, isDirty },\n        } = useForm({\n          defaultValues: {\n            firstName: '',\n            lastName: '',\n          },\n        });\n\n        updatedDirtyFields = dirtyFields;\n        updatedDirty = isDirty;\n\n        React.useEffect(() => {\n          setTimeout(() => {\n            reset(\n              {\n                firstName: 'bill',\n                lastName: 'luo',\n              },\n              { keepDirtyValues: true },\n            );\n            setShowButton(true);\n          }, 500);\n        }, [reset]);\n\n        return (\n          <form\n            onSubmit={handleSubmit((data) => {\n              submittedValue = data;\n            })}\n          >\n            <Controller\n              control={control}\n              render={({ field }) => {\n                return <input {...field} placeholder=\"First Name\" />;\n              }}\n              name={'firstName'}\n            />\n            <Controller\n              control={control}\n              render={({ field }) => {\n                return <input {...field} placeholder=\"Last Name\" />;\n              }}\n              name={'lastName'}\n            />\n\n            {showButton && (\n              <button\n                type=\"button\"\n                onClick={() => {\n                  reset();\n                }}\n              >\n                reset\n              </button>\n            )}\n\n            <button>submit</button>\n          </form>\n        );\n      }\n\n      it('should only update new reset values', async () => {\n        render(<App />);\n\n        await waitFor(() =>\n          expect(\n            (screen.getByPlaceholderText('First Name') as HTMLInputElement)\n              .value,\n          ).toEqual('bill'),\n        );\n\n        fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n        expect(updatedDirtyFields).toEqual({});\n        expect(updatedDirty).toBeFalsy();\n\n        expect(\n          (screen.getByPlaceholderText('First Name') as HTMLInputElement).value,\n        ).toEqual('bill');\n\n        expect(updatedDirtyFields).toEqual({});\n        expect(updatedDirty).toBeFalsy();\n\n        fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n        await waitFor(() =>\n          expect(submittedValue).toEqual({\n            firstName: 'bill',\n            lastName: 'luo',\n          }),\n        );\n      });\n\n      it('should only update none dirty fields and keep other values updated', async () => {\n        render(<App />);\n\n        fireEvent.change(screen.getByPlaceholderText('First Name'), {\n          target: {\n            value: 'test',\n          },\n        });\n\n        await waitFor(() =>\n          expect(\n            (screen.getByPlaceholderText('Last Name') as HTMLInputElement)\n              .value,\n          ).toEqual('luo'),\n        );\n\n        expect(updatedDirtyFields).toEqual({\n          firstName: true,\n        });\n        expect(updatedDirty).toBeTruthy();\n\n        fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n        await waitFor(() =>\n          expect(submittedValue).toEqual({\n            firstName: 'test',\n            lastName: 'luo',\n          }),\n        );\n\n        fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n        expect(\n          (screen.getByPlaceholderText('First Name') as HTMLInputElement).value,\n        ).toEqual('bill');\n\n        expect(updatedDirtyFields).toEqual({});\n        expect(updatedDirty).toBeFalsy();\n\n        fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n        await waitFor(() =>\n          expect(submittedValue).toEqual({\n            firstName: 'bill',\n            lastName: 'luo',\n          }),\n        );\n      });\n    });\n  });\n\n  it('should allow to reset unmounted field array', () => {\n    type FormValues = {\n      test: { name: string }[];\n    };\n\n    const FieldArray = ({\n      control,\n      register,\n    }: {\n      control: Control<FormValues>;\n      register: UseFormRegister<FormValues>;\n    }) => {\n      const { fields, append } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <div>\n          {fields.map((field, index) => {\n            return (\n              <input\n                key={field.id}\n                {...register(`test.${index}.name` as const)}\n              />\n            );\n          })}\n          <button\n            onClick={() => {\n              append({ name: '' });\n            }}\n          >\n            append\n          </button>\n        </div>\n      );\n    };\n\n    const App = () => {\n      const [show, setShow] = React.useState(true);\n      const { control, register, reset } = useForm<FormValues>();\n\n      return (\n        <div>\n          {show && <FieldArray control={control} register={register} />}\n          <button\n            onClick={() => {\n              setShow(!show);\n            }}\n          >\n            toggle\n          </button>\n          <button\n            onClick={() => {\n              reset({\n                test: [{ name: 'test' }],\n              });\n            }}\n          >\n            reset\n          </button>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'append' }));\n    fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n    expect(screen.getAllByRole('textbox').length).toEqual(2);\n\n    fireEvent.click(screen.getByRole('button', { name: 'toggle' }));\n    fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n    fireEvent.click(screen.getByRole('button', { name: 'toggle' }));\n\n    expect(screen.getAllByRole('textbox').length).toEqual(1);\n  });\n\n  it('should only return register input when reset is invoked with shouldUnregister:true', async () => {\n    let submittedData = {};\n\n    const App = () => {\n      const { reset, handleSubmit } = useForm({\n        defaultValues: {\n          test: 'bill',\n        },\n        shouldUnregister: true,\n      });\n\n      return (\n        <form\n          onSubmit={handleSubmit((data) => {\n            submittedData = data;\n          })}\n        >\n          <button>submit</button>\n          <button\n            type={'button'}\n            onClick={() => {\n              reset({\n                test: '1234',\n              });\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(submittedData).toEqual({});\n\n    fireEvent.click(screen.getByRole('button', { name: 'reset' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(submittedData).toEqual({});\n  });\n\n  it('should update controlled input correctly with shouldUnregister set to true', () => {\n    function App() {\n      const { register, reset, control } = useForm({\n        defaultValues: { uncontrolled: '', control: '' },\n        shouldUnregister: true,\n      });\n\n      return (\n        <form>\n          <input {...register('uncontrolled')} />\n          <Controller\n            render={({ field }) => (\n              <input\n                ref={field.ref}\n                value={field.value}\n                onChange={field.onChange}\n              />\n            )}\n            name=\"control\"\n            control={control}\n          />\n\n          <button\n            type=\"button\"\n            onClick={() => {\n              reset({ uncontrolled: 'uncontrolled', control: 'control' });\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(\n      (screen.getAllByRole('textbox')[0] as HTMLInputElement).value,\n    ).toEqual('uncontrolled');\n    expect(\n      (screen.getAllByRole('textbox')[1] as HTMLInputElement).value,\n    ).toEqual('control');\n  });\n\n  it('should keep reset value for conditionally mounted controlled fields with shouldUnregister', async () => {\n    let submittedData = {};\n\n    const App = () => {\n      const { control, watch, handleSubmit, reset } = useForm<{\n        name: string;\n        age: string;\n      }>({\n        shouldUnregister: true,\n        defa