+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/formState.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport { Controller } from '../../controller';\nimport type { Control, FormState, UseFormGetFieldState } from '../../types';\nimport { useController } from '../../useController';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\nimport noop from '../../utils/noop';\n\ndescribe('formState', () => {\n  describe('isValid', () => {\n    it('should return isValid correctly with resolver', async () => {\n      let isValidValue = false;\n\n      const Component = () => {\n        const {\n          register,\n          formState: { isValid },\n        } = useForm<{ test: string }>({\n          mode: 'onChange',\n          resolver: async (data) => {\n            return {\n              values: data.test ? data : {},\n              errors: data.test\n                ? {}\n                : {\n                    test: {\n                      message: 'issue',\n                      type: 'test',\n                    },\n                  },\n            };\n          },\n        });\n\n        isValidValue = isValid;\n        return <input {...register('test')} />;\n      };\n\n      render(<Component />);\n\n      expect(isValidValue).toBeFalsy();\n\n      fireEvent.input(screen.getByRole('textbox'), {\n        target: {\n          value: 'test',\n        },\n      });\n\n      await waitFor(() => expect(isValidValue).toBeTruthy());\n    });\n\n    it('should return true for onBlur mode by default', async () => {\n      const App = () => {\n        const {\n          formState: { isValid },\n        } = useForm<{ test: string }>({\n          mode: VALIDATION_MODE.onBlur,\n        });\n\n        return <p>{isValid ? 'valid' : 'invalid'}</p>;\n      };\n\n      render(<App />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n    });\n\n    it('should return true for onChange mode by default', async () => {\n      const App = () => {\n        const {\n          formState: { isValid },\n        } = useForm<{ test: string }>({\n          mode: VALIDATION_MODE.onChange,\n        });\n\n        return <p>{isValid ? 'valid' : 'invalid'}</p>;\n      };\n\n      render(<App />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n    });\n\n    it('should return true for all mode by default', async () => {\n      const App = () => {\n        const {\n          formState: { isValid },\n        } = useForm<{ test: string }>({\n          mode: VALIDATION_MODE.all,\n        });\n\n        return <p>{isValid ? 'valid' : 'invalid'}</p>;\n      };\n\n      render(<App />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n    });\n\n    it('should return false when default value is not valid value', async () => {\n      const { result } = renderHook(() => {\n        const methods = useForm<{ input: string; issue: string }>({\n          mode: VALIDATION_MODE.onChange,\n        });\n\n        methods.formState.isValid;\n\n        return methods;\n      });\n\n      await act(async () => {\n        result.current.register('issue', { required: true });\n        result.current.setValue('issue', '', { shouldValidate: true });\n      });\n\n      expect(result.current.formState.isValid).toBeFalsy();\n    });\n\n    it('should return false when custom register with validation', async () => {\n      const { result } = renderHook(() =>\n        useForm<{ input: string; issue: string }>({\n          mode: VALIDATION_MODE.onChange,\n        }),\n      );\n\n      result.current.formState.isValid;\n\n      await act(async () => {\n        result.current.register('issue', { required: true });\n      });\n\n      expect(result.current.formState.isValid).toBeFalsy();\n    });\n\n    it('should update valid when toggle Controller', async () => {\n      const App = () => {\n        const {\n          control,\n          watch,\n          formState: { isValid },\n        } = useForm({\n          mode: 'onChange',\n          shouldUnregister: true,\n        });\n        const test = watch('test');\n\n        return (\n          <div>\n            <p>{isValid ? 'valid' : 'invalid'}</p>\n            <Controller\n              control={control}\n              rules={{ required: true }}\n              render={({ field }) => (\n                <select {...field} data-testid=\"select\">\n                  <option value={''}></option>\n                  <option value={'test'}>test</option>\n                  <option value={'test1'}>test1</option>\n                </select>\n              )}\n              name={'test'}\n            />\n\n            {test === 'test1' && (\n              <>\n                <Controller\n                  control={control}\n                  render={({ field }) => <input {...field} />}\n                  rules={{ required: true }}\n                  name={'first.test'}\n                />\n                <Controller\n                  control={control}\n                  render={({ field }) => <input {...field} />}\n                  rules={{ required: true }}\n                  name={'first.test1'}\n                />\n              </>\n            )}\n          </div>\n        );\n      };\n\n      render(<App />);\n\n      expect(screen.getByText('invalid')).toBeVisible();\n\n      fireEvent.change(screen.getByTestId('select'), {\n        target: {\n          value: 'test',\n        },\n      });\n\n      expect(await screen.findByText('valid')).toBeVisible();\n\n      fireEvent.change(screen.getByTestId('select'), {\n        target: {\n          value: 'test1',\n        },\n      });\n\n      expect(await screen.findByText('invalid')).toBeVisible();\n\n      fireEvent.change(screen.getByTestId('select'), {\n   