alsy();\n  });\n\n  it('should be a proxy object that hasOwnProperty works on', () => {\n    const { result } = renderHook(() => useForm());\n\n    expect(result.current.formState).toHaveProperty('hasOwnProperty');\n  });\n\n  describe('when using with reset API', () => {\n    type FormValues = {\n      foo: string;\n      foo1: string;\n    };\n\n    it('should render isValid as true with reset at useEffect with valid data', async () => {\n      function Component() {\n        const {\n          register,\n          control,\n          formState: { isValid },\n          reset,\n        } = useForm<FormValues>({\n          mode: 'onBlur',\n          defaultValues: { foo: '', foo1: '' },\n        });\n\n        React.useEffect(() => {\n          reset({ foo: 'test', foo1: 'test2' });\n        }, [reset]);\n\n        return (\n          <div>\n            <h2>Form with controlled input</h2>\n            <Controller\n              name=\"foo\"\n              rules={{ required: true }}\n              control={control}\n              render={({ field }) => <input {...field} />}\n            />\n            <input {...register('foo1', { required: true })} />\n            {isValid ? 'valid' : 'nope'}\n          </div>\n        );\n      }\n\n      render(<Component />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n    });\n\n    it('should render isValid as false with reset at useEffect with valid data', async () => {\n      function Component() {\n        const {\n          register,\n          control,\n          formState: { isValid },\n          reset,\n        } = useForm<FormValues>({\n          mode: 'onBlur',\n          defaultValues: { foo: '', foo1: '' },\n        });\n\n        React.useEffect(() => {\n          reset({ foo: 'test', foo1: '' });\n        }, [reset]);\n\n        return (\n          <div>\n            <h2>Form with controlled input</h2>\n            <Controller\n              name=\"foo\"\n              rules={{ required: true