+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/subscribe.test.tsx"],"sourcesContent":["import React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\n\nimport type { UseFormSubscribe } from '../../types';\nimport { useForm } from '../../useForm';\nimport { useFormState } from '../../useFormState';\n\ndescribe('subscribe', () => {\n  it('should properly handle multiple subscriptions', async () => {\n    const callbackFn1 = jest.fn();\n    const callbackFn2 = jest.fn();\n\n    function ChildComp({\n      subscribe,\n    }: {\n      subscribe: UseFormSubscribe<{\n        first: string;\n        sec: string;\n      }>;\n    }) {\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            dirtyFields: true,\n          },\n          name: 'first',\n          callback: callbackFn2,\n        });\n      }, [subscribe]);\n      return null;\n    }\n    const App = () => {\n      const { register, subscribe } = useForm({\n        defaultValues: {\n          first: '',\n          sec: '',\n        },\n      });\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          name: 'sec',\n          callback: callbackFn1,\n        });\n      }, [subscribe]);\n      return (\n        <form>\n          <input {...register('first')} />\n          <input {...register('sec')} />\n          <ChildComp subscribe={subscribe} />\n        </form>\n      );\n    };\n    render(<App />);\n\n    fireEvent.input(screen.getAllByRole('textbox')[0], {\n      target: { name: 'first', value: 'test' },\n    });\n\n    expect(callbackFn2).toHaveBeenCalledTimes(1);\n    expect(callbackFn1).toHaveBeenCalledTimes(0);\n\n    fireEvent.input(screen.getAllByRole('textbox')[1], {\n      target: { name: 'sec', value: 'test' },\n    });\n\n    expect(callbackFn2).toHaveBeenCalledTimes(1);\n    expect(callbackFn1).toHaveBeenCalledTimes(1);\n  });\n\n  it('should only react to formState changes it subscribes to', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { register, subscribe, control } = useForm({\n        defaultValues: {\n          first: '',\n          sec: '',\n        },\n      });\n\n      const fieldFormState = useFormState({\n        name: 'first',\n        control,\n      });\n\n      fieldFormState.touchedFields;\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          name: 'sec',\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('first')} />\n          <input {...register('sec')} />\n        </form>\n      );\n    };\n    render(<App />);\n\n    fireEvent.blur(screen.getAllByRole('textbox')[1]);\n\n    fireEvent.input(screen.getAllByRole('textbox')[1], {\n      target: { value: 'test' },\n    });\n\n    fireEvent.input(screen.getAllByRole('textbox')[1], {\n      target: { value: 'test2' },\n    });\n\n    expect(callbackFn).toHaveBeenCalledTimes(2);\n  });\n\n  it('should allow subscribing to submit state updates', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { handleSubmit, subscribe } = useForm();\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            isSubmitted: true,\n            submitCount: true,\n          },\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form onSubmit={handleSubmit(() => undefined)}>\n          <button type=\"submit\">Submit</button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'Submit' }));\n\n    await waitFor(() =>\n      expect(callbackFn).toHaveBeenCalledWith(\n        expect.objectContaining({\n          isSubmitted: true,\n          submitCount: 1,\n        }),\n      ),\n    );\n  });\n\n  it('should not call subscribe callback when setValue is called with the same value and shouldDirty option', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { register, setValue, subscribe } = useForm({\n        defaultValues: {\n          test: 'initial',\n        },\n      });\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button\n            type=\"button\"\n            onClick={() => setValue('test', 'initial', { shouldDirty: true })}\n          >\n            Set same\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'Set same' }));\n\n    expect(callbackFn).not.toHaveBeenCalled();\n  });\n\n  it('should not call subscribe callback when setValue is called with the same value and shouldTouch/shouldValidate options', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { register, setValue, subscribe } = useForm({\n        defaultValues: {\n          test: 'initial',\n        },\n      });\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button\n            type=\"button\"\n            onClick={() =>\n              setValue('test', 'initial', {\n                shouldTouch: true,\n                shouldValidate: true,\n              })\n            }\n          >\n            Set same\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'Set same' }));\n\n    expect(callbackFn).not.toHaveBeenCalled();\n  });\n\n  it('should call subscribe callback with a values snapshot', async () => {\n    const callbackFn = jest.fn();\n    let capturedValues: Record<string, unknown> | undefined;\n\n    const App = () => {\n      const { register, setValue, subscribe } = useForm({\n        defaultValues: {\n          test: '',\n        },\n      });\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          callback: (data) => {\n            capturedValues = data.values as Record<string, unknown>;\n            callbackFn(data);\n          },\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button type=\"button\" onClick={() => setValue('test', 'hello')}>\n            Update\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'Update' }));\n\n    expect(callbackFn).toHaveBeenCalledTimes(1);\n    expect(capturedValues).toEqual({ test: 'hello' });\n  });\n\n  it('should keep isDirty true when reset keeps values and updates defaultValues', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { register, reset, subscribe } = useForm({\n        defaultValues: {\n          name: 'name',\n          description: 'a',\n        },\n      });\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            isDirty: true,\n            values: true,\n          },\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('name')} />\n          <input {...register('description')} />\n          <button\n            type=\"button\"\n            onClick={() =>\n              reset(\n                {\n                  name: 'server-name',\n                  description: 'a',\n                },\n                {\n                  keepValues: true,\n                },\n              )\n            }\n          >\n            sync defaults\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.input(screen.getAllByRole('textbox')[0], {\n      target: { value: 'client-name' },\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'sync defaults' }));\n\n    await waitFor(() =>\n      expect(callbackFn).toHaveBeenLastCalledWith(\n        expect.objectContaining({\n          isDirty: true,\n          defaultValues: {\n            name: 'server-name',\n            description: 'a',\n          },\n          values: {\n            name: 'client-name',\n            description: 'a',\n          },\n        }),\n      ),\n    );\n  });\n});\n"],"names":["describe","it","callbackFn1","jest","fn","callbackFn2","ChildComp","subscribe","React","useEffect","formState","dirtyFields","name","callback","App","register","useForm","defaultValues","first","sec","values","form","input","render","fireEvent","screen","getAllByRole","target","value","expect","toHaveBeenCalledTimes","callbackFn","control","fieldFormState","useFormState","touchedFields","blur","handleSubmit","isSubmitted","submitCount","onSubmit","undefined","button","type","click","getByRole","waitFor","toHaveBeenCalledWith","objectContaining","setValue","test","onClick","shouldDirty","not","toHaveBeenCalled","shouldTouch","shouldValidate","capturedValues","data","toEqual","reset","description","isDirty","keepValues","toHaveBeenLastCalledWith"],"mappings":";;;;8DAAkB;wBACiC;yBAG3B;8BACK;;;;;;AAE7BA,SAAS,aAAa;IACpBC,GAAG,iDAAiD;QAClD,MAAMC,cAAcC,KAAKC,EAAE;QAC3B,MAAMC,cAAcF,KAAKC,EAAE;QAE3B,SAASE,UAAU,EACjBC,SAAS,EAMV;YACCC,cAAK,CAACC,SAAS,CAAC;gBACd,OAAOF,UAAU;oBACfG,WAAW;wBACTC,aAAa;oBACf;oBACAC,MAAM;oBACNC,UAAUR;gBACZ;YACF,GAAG;gBAACE;aAAU;YACd,OAAO;QACT;QACA,MAAMO,MAAM;YACV,MAAM,EAAEC,Q