+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray/replace.test.tsx"],"sourcesContent":["import React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport { useController } from '../../useController';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\nimport { FormProvider } from '../../useFormContext';\n\ninterface TestValue {\n  x: string;\n}\n\ninterface DefaultValues {\n  test: TestValue[];\n}\n\nlet i = 0;\n\njest.mock('../../logic/generateId', () => () => String(i++));\n\ndescribe('replace', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  it('should replace fields correctly', () => {\n    let currentFields: any = [];\n    const defaultValues: DefaultValues = {\n      test: [{ x: '101' }, { x: '102' }, { x: '103' }],\n    };\n\n    const labelSingle = 'replace';\n\n    const labelBatch = 'replaceBatch';\n\n    const Component = () => {\n      const { register, control } = useForm<DefaultValues>({\n        defaultValues,\n      });\n      const { fields, replace } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      currentFields = fields;\n\n      const handleSingleReplace = () => replace({ x: '201' });\n\n      const handleBatchReplace = () => replace([{ x: '301' }, { x: '302' }]);\n\n      return (\n        <form>\n          {fields.map((field, index) => {\n            return (\n              <input key={field.id} {...register(`test.${index}.x` as const)} />\n            );\n          })}\n          <button type=\"button\" onClick={handleSingleReplace}>\n            {labelSingle}\n          </button>\n          <button type=\"button\" onClick={handleBatchReplace}>\n            {labelBatch}\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: labelSingle }));\n\n    expect(currentFields).toEqual([{ id: '6', x: '201' }]);\n\n    fireEvent.click(screen.getByRole('button', { name: labelBatch }));\n\n    expect(currentFields).toEqual([\n      { id: '8', x: '301' },\n      { id: '9', x: '302' },\n    ]);\n  });\n  it('should not omit keyName when provided', async () => {\n    type FormValues = {\n      test: {\n        test: string;\n        id: string;\n      }[];\n    };\n\n    const App = () => {\n      const [data, setData] = React.useState<FormValues>();\n      const { control, register, handleSubmit } = useForm<FormValues>({\n        defaultValues: {\n          test: [\n            { id: '1234', test: 'data' },\n            { id: '4567', test: 'data1' },\n          ],\n        },\n      });\n\n      const { fields, replace } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(setData)}>\n          {fields.map((field, index) => {\n            return <input key={field.id} {...register(`test.${index}.test`)} />;\n          })}\n          <button\n            type={'button'}\n            onClick={() => {\n              replace([{ id: 'test', test: 'data' }]);\n            }}\n          >\n            replace\n          </button>\n          <button>submit</button>\n          <p>{JSON.stringify(data)}</p>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'replace' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(\n      await screen.findByText('{\"test\":[{\"id\":\"test\",\"test\":\"data\"}]}'),\n    ).toBeVisible();\n  });\n\n  it('should not omit keyName when provided and defaultValue is empty', async () => {\n    type FormValues = {\n      test: {\n        test: string;\n        id: string;\n      }[];\n    };\n    let k = 0;\n\n    const App = () => {\n      const [data, setData] = React.useState<FormValues>();\n      const { control, register, handleSubmit } = useForm<FormValues>();\n\n      const { fields, append, replace } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(setData)}>\n          {fields.map((field, index) => {\n            return <input key={field.id} {...register(`test.${index}.test`)} />;\n          })}\n          <button\n            type={'button'}\n            onClick={() => {\n              replace([{ id: 'whatever', test: 'data' }]);\n            }}\n          >\n            replace\n          </button>\n\n          <button\n            type={'button'}\n            onClick={() => {\n              append({\n                id: 'whatever' + k,\n                test: '1234' + k,\n              });\n              k = 1;\n            }}\n          >\n            append\n          </button>\n          <button>submit</button>\n          <p>{JSON.stringify(data)}</p>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'append' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'replace' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(\n      await screen.findByText('{\"test\":[{\"id\":\"whatever\",\"test\":\"data\"}]}'),\n    ).toBeVisible();\n  });\n\n  it('should not replace errors state', async () => {\n    const App = () => {\n      const {\n        control,\n        register,\n        trigger,\n        formState: { errors },\n      } = useForm({\n        defaultValues: {\n          test: [\n            {\n              firstName: '',\n            },\n          ],\n        },\n      });\n      const { fields, replace } = useFieldArray({\n        name: 'test',\n        control,\n      });\n\n      React.useEffect(() => {\n        trigger();\n      }, [trigger]);\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input\n              key={field.id}\n              {...register(`test.${i}.firstName` as const, {\n                required: 'This is required',\n              })}\n            />\n          ))}\n          <p>{errors?.test?.[0]?.firstName?.message}</p>\n          <button\n            type={'button'}\n            onClick={() =>\n              replace([\n                {\n                  firstName: 'firstName',\n                },\n              ])\n            }\n          >\n            update\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    expect(await screen.findByText('This is required')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('This is required')).toBeVisible();\n  });\n\n  it('should not affect other formState during replace action', () => {\n    const ControlledInput = ({ index }: { index: number }) => {\n      const { field } = useController({\n        name: `fieldArray.${index}.firstName`,\n      });\n      return <input {...field} />;\n    };\n\n    const defaultValue = {\n      firstName: 'test',\n    };\n\n    const FieldArray = () => {\n      const { fields, replace } = useFieldArray({\n        name: 'fieldArray',\n      });\n\n      React.useEffect(() => {\n        replace([defaultValue]);\n      }, [replace]);\n\n      return (\n        <div>\n          {fields.map((field, index) => {\n            return <ControlledInput key={field.id} index={index} />;\n          })}\n\n          <button type=\"button\" onClick={() => replace(defaultValue)}>\n            replace\n          </button>\n        </div>\n      );\n    };\n\n    function App() {\n      const form = useForm({\n        mode: 'onChange',\n      });\n      const [, updateState] = React.useState(0);\n\n      return (\n        <FormProvider {...form}>\n          <FieldArray />\n          <p>{JSON.stringify(form.formState.touchedFields)}</p>\n          <button onClick={() => updateState(1)}>updateState</button>\n        </FormProvider>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.focus(screen.getByRole('textbox'));\n    fireEvent.blur(screen.getByRole('textbox'));\n    fireEvent.click(screen.getByRole('button', { name: 'replace' }));\n    fireEvent.click(screen.getByRole('button', { name: 'updateState' }));\n\n    expect(\n      screen.getByText('{\"fieldArray\":[{\"firstName\":true}]}'),\n    ).toBeVisible();\n  });\n\n  describe('with resolver', () => {\n    it('should not invoke resolver per register during replace, but run after replace completes', async () => {\n      const resolver = jest\n        .fn()\n        .mockImplementation((values) => ({ values, errors: {} }));\n\n      const App = () => {\n        const { register, formState, control } = useForm<{\n          test: { value: string }[];\n        }>({\n          mode: VALIDATION_MODE.onTouched,\n          resolver,\n          defaultValues: { test: [] },\n        });\n\n        formState.isValid;\n\n        const { fields, replace } = useFieldArray({ control, name: 'test' });\n\n        return (\n          <form>\n            {fields.map((f, i) => (\n              <input key={f.id} {...register(`test.${i}.value` as const)} />\n            ))}\n            <button\n              type=\"button\"\n              onClick={() =>\n                replace([{ value: '1' }, { value: '2' }, { value: '3' }])\n              }\n            >\n              replace\n            </button>\n          </form>\n        );\n      };\n\n      render(<App />);\n\n      // wait for any initial resolver run triggered by isValid subscription\n      await waitFor(() =>\n        expect(resolver.mock.calls.length).toBeGreaterThanOrEqual(1),\n      );\n      const initialCalls = resolver.mock.calls.length;\n\n      fireEvent.click(screen.getByRole('button', { name: 'replace' }));\n\n      // ensure 3 inputs are mounted (all fields registered)\n      await waitFor(async () => {\n        expect((await screen.findAllByRole('textbox')).length).toBe(3);\n      });\n\n      // assert only two extra resolver calls: array-scoped + final isValid\n      await waitFor(() =>\n        expect(resolver.mock.calls.length).toBe(initialCalls + 2),\n      );\n    });\n  });\n});\n"],"names":["jest","mock","String","i","describe","beforeEach","it","currentFields","defaultValues","test","x","labelSingle","labelBatch","Component","register","control","useForm","fields","replace","useFieldArray","name","handleSingleReplace","handleBatchReplace","form","map","field","index","input","key","id","button","type","onClick","render","fireEvent","click","screen","getByRole","expect","toEqual","App","data","setData","React","useState","handleSubmit","onSubmit","p","JSON","stringify","findByText","toBeVisible","k","append","trigger","formState","errors","firstName","useEffect","required","message","ControlledInput","useController","defaultValue","FieldArray","div","mode","updateState","FormProvider","touchedFields","focus","blur","getByText","resolver","fn","mockImplementation","values","VALIDATION_MODE","onTouched","isValid","f","value","waitFor","calls","length","toBeGreaterThanOrEqual","initialCalls","findAllByRole","toBe"],"mappings":";AAmBAA,KAAKC,IAAI,CAAC,0BAA0B,IAAM,IAAMC,OAAOC;;;;8DAnBrC;wBACiC;2BAEnB;+BACF;+BACA;yBACN;gCACK;;;;;;AAU7B,IAAIA,IAAI;AAIRC,SAAS,WAAW;IAClBC,WAAW;QACTF,IAAI;IACN;IAEAG,GAAG,mCAAmC;QACpC,IAAIC,gBAAqB,EAAE;QAC3B,MAAMC,gBAA+B;YACnCC,MAAM;gBAAC;oBAAEC,GAAG;gBAAM;gBAAG;oBAAEA,GAAG;gBAAM;gBAAG;oBAAEA,GAAG;gBAAM;aAAE;QAClD;QAEA,MAAMC,cAAc;QAEpB,MAAMC,aAAa;QAEnB,MAAMC,YAAY;YAChB,MAAM,EAAEC,QAAQ,EAAEC,OAAO,EAAE,GAAGC,IAAAA,gBAAO,EAAgB;gBACnDR;YACF;YACA,MAAM,EAAES,MAAM,EAAEC,OAAO,EAAE,GAAGC,IAAAA,4BAAa,EAAC;gBACxCJ;gBACAK,MAAM;YACR;YAEAb,gBAAgBU;YAEhB,MAAMI,sBAAsB,IAAMH,QAAQ;oBAAER,GAAG;gBAAM;YAErD,MAAMY,qBAAqB,IAAMJ,QAAQ;oBAAC;wBAAER,GAAG;oBAAM;oBAAG;wBAAEA,GAAG;oBAAM;iBAAE;YAErE,qBACE,6BAACa,cACEN,OAAOO,GAAG,CAAC,CAACC,OAAOC;gBAClB,qBACE,6BAACC;oBAAMC,KAAKH,MAA