on\n    await act(async () => {\n      result.current.setValues({ firstName: 'John' });\n    });\n\n    // Value is set but validation is not triggered\n    expect(result.current.getValues().firstName).toBe('John');\n    // isValid might still be false because validation wasn't re-run\n    expect(result.current.formState.isValid).toBe(false);\n  });\n});\n"],"names":["describe","it","result","renderHook","useForm","defaultValues","a","b","act","current","setValues","expect","getValues","toEqual","values","control","nextSpy","jest","spyOn","_subjects","state","valueNotifications","mock","calls","filter","call","toHaveLength","register","setValue","shouldValidate","terminal","at","name","toBeUndefined","type","Component","firstName","Controller","render","field","input","button","onClick","fireEvent","click","screen","getByRole","toHaveValue","user","profile","lastName","address","city","aria-label","getByLabelText","nested","nextA","nextB","toBe","ref","document","createElement","deliveredValues","unsubscribe","subscribe","formState","callback","data","push","length","toBeGreaterThan","mode","required","isValid","shouldDirty","shouldTouch","dirtyFields","touchedFields","email","pattern","value","message","errors","trigger","toBeDefined","username","age","minLength","min"],"mappings":";;;;8DAAkB;wBAOX;4BAEoB;yBACH;;;;;;AAExBA,SAAS,aAAa;IACpBC,GAAG,uCAAuC;QACxC,MAAM,EAAEC,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAC5BC,IAAAA,gBAAO,EAA2B;gBAChCC,eAAe;oBAAEC,GAAG;oBAAKC,GAAG;gBAAI;YAClC;QAGF,MAAMC,IAAAA,WAAG,EAAC;YACRN,OAAOO,OAAO,CAACC,SAAS,CAAC;gBACvBJ,GAAG;gBACHC,GAAG;YACL;QACF;QAEAI,OAAOT,OAAOO,OAAO,CAACG,SAAS,IAAIC,OAAO,CAAC;YACzCP,GAAG;YACHC,GAAG;QACL;IACF;IAEAN,GAAG,mCAAmC;QACpC,MAAM,EAAEC,MAAM,EAAE,GAAGC,IAAAA,kBAAU,EAAC,IAC5BC,IAAAA,gBAAO,EAA2B;gBAChCC,eAAe;oBAAEC,GAAG;oBAAKC,GAAG;gBAAI;YAClC;QAGF,MAAMC,IAAAA,WAAG,EAAC;YACRN,OAAOO,OAAO,CAACC,SAAS,CAAC,CAACI,SAAY,CAAA;oBACpCR,GAAGQ,OAAOR,CAAC,GAAG;oBACdC,GAAGO,OAAOP,CAAC,GAAG;gBAChB,CAAA;QACF;QAEAI,OAAOT,OAAOO,OAAO,CAACG,