+{"version":3,"sources":["/workspace/repo/src/useFormContext.tsx"],"sourcesContent":["import React from 'react';\n\nimport type {\n  Control,\n  FieldValues,\n  FormProviderProps,\n  UseFormReturn,\n} from './types';\nimport { HookFormControlContext } from './useFormControlContext';\n\nconst HookFormContext = React.createContext<UseFormReturn | null>(null);\nHookFormContext.displayName = 'HookFormContext';\n\n/**\n * This custom hook allows you to access the form context. useFormContext is intended to be used in deeply nested structures, where it would become inconvenient to pass the context as a prop. To be used with {@link FormProvider}.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/useformcontext) • [Demo](https://codesandbox.io/s/react-hook-form-v7-form-context-ytudi)\n *\n * @returns return all useForm methods\n *\n * @example\n * ```tsx\n * function App() {\n *   const methods = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   return (\n *     <FormProvider {...methods} >\n *       <form onSubmit={methods.handleSubmit(onSubmit)}>\n *         <NestedInput />\n *         <input type=\"submit\" />\n *       </form>\n *     </FormProvider>\n *   );\n * }\n *\n *  function NestedInput() {\n *   const { register } = useFormContext(); // retrieve all hook methods\n *   return <input {...register(\"test\")} />;\n * }\n * ```\n */\nexport const useFormContext = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(): UseFormReturn<TFieldValues, TContext, TTransformedValues> =>\n  React.useContext(HookFormContext) as UseFormReturn<\n    TFieldValues,\n    TContext,\n    TTransformedValues\n  >;\n\n/**\n * A provider component that propagates the `useForm` methods to all children components via [React Context](https://react.dev/reference/react/useContext) API. To be used with {@link useFormContext}.\n *\n * @remarks\n * [API](https://react-hook-form.com/docs/useformcontext) • [Demo](https://codesandbox.io/s/react-hook-form-v7-form-context-ytudi)\n *\n * @param props - all useForm methods\n *\n * @example\n * ```tsx\n * function App() {\n *   const methods = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   return (\n *     <FormProvider {...methods} >\n *       <form onSubmit={methods.handleSubmit(onSubmit)}>\n *         <NestedInput />\n *         <input type=\"submit\" />\n *       </form>\n *     </FormProvider>\n *   );\n * }\n *\n *  function NestedInput() {\n *   const { register } = useFormContext(); // retrieve all hook methods\n *   return <input {...register(\"test\")} />;\n * }\n * ```\n */\nexport const FormProvider = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>({\n  children,\n  watch,\n  getValues,\n  getFieldState,\n  setError,\n  clearErrors,\n  setValue,\n  setValues,\n  trigger,\n  formState,\n  resetField,\n  reset,\n  handleSubmit,\n  unregister,\n  control,\n  register,\n  setFocus,\n  subscribe,\n}: FormProviderProps<TFieldValues, TContext, TTransformedValues>) => {\n  const memoizedValue = React.useMemo(\n    () => ({\n      watch,\n      getValues,\n      getFieldState,\n      setError,\n      clearErrors,\n      setValue,\n      setValues,\n      trigger,\n      formState,\n      resetField,\n      reset,\n      handleSubmit,\n      unregister,\n      control,\n      register,\n      setFocus,\n      subscribe,\n    }),\n    [\n      clearErrors,\n      control,\n      formState,\n      getFieldState,\n      getValues,\n      handleSubmit,\n      register,\n      reset,\n      resetField,\n      setError,\n      setFocus,\n      setValue,\n      setValues,\n      subscribe,\n      trigger,\n      unregister,\n      watch,\n    ],\n  );\n\n  return (\n    <HookFormContext.Provider value={memoizedValue as unknown as UseFormReturn}>\n      <HookFormControlContext.Provider value={memoizedValue.control as Control}>\n        {children}\n      </HookFormControlContext.Provider>\n    </HookFormContext.Provider>\n  );\n};\n"],"names":["FormProvider","useFormContext","HookFormContext","React","createContext","displayName","useContext","children","watch","getValues","getFieldState","setError","clearErrors","setValue","setValues","trigger","formState","resetField","reset","handleSubmit","unregister","control","register","setFocus","subscribe","memoizedValue","useMemo","Provider","value","HookFormControlContext"],"mappings":";;;;;;;;;;;QAoFaA;eAAAA;;QAzCAC;eAAAA;;;8DA3CK;uCAQqB;;;;;;AAEvC,MAAMC,gCAAkBC,cAAK,CAACC,aAAa,CAAuB;AAClEF,gBAAgBG,WAAW,GAAG;AAgCvB,MAAMJ,iBAAiB,IAK5BE,cAAK,CAACG,UAAU,CAACJ;AAoCZ,MAAMF,eAAe,CAI1B,EACAO,QAAQ,EACRC,KAAK,EACLC,SAAS,EACTC,aAAa,EACbC,QAAQ,EACRC,WAAW,EACXC,QAAQ,EACRC,SAAS,EACTC,OAAO,EACPC,SAAS,EACTC,UAAU,EACVC,KAAK,EACLC,YAAY,EACZC,UAAU,EACVC,OAAO,EACPC,QAAQ,EACRC,QAAQ,EACRC,SAAS,EACqD;IAC9D,MAAMC,gBAAgBtB,cAAK,CAACuB,OAAO,CACjC,IAAO,CAAA;YACLlB;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;YACAC;QACF,CAAA,GACA;QACEZ;QACAS;QACAL;QACAN;QACAD;QACAU;QACAG;QACAJ;QACAD;QACAN;QACAY;QACAV;QACAC;QACAU;QACAT;QACAK;QACAZ;KACD;IAGH,qBACE,6BAACN,gBAAgByB,QAAQ;QAACC,OAAOH;qBAC/B,6BAACI,6CAAsB,CAACF,QAAQ;QAACC,OAAOH,cAAcJ,OAAO;OAC1Dd;AAIT"}
